-- Usar CTE para buscar cronograma_id dinamicamente
WITH cronograma_info AS (
  SELECT id FROM planejamento_cronogramas WHERE nome = 'Rev. 05' AND obra_id = 'obra2' LIMIT 1
)
ON CONFLICT (codigo, cronograma_id, obra_id) DO NOTHING;

